"console.log("Injecting JS error event listener");
window.addEventListener('error', function(event) {
    window.webkit.messageHandlers.jsError.postMessage({
        timestamp : Date.now(),
        message: event.message,
        filename: event.filename,
        lineno: event.lineno,
        colno: event.colno,
        error: (event.error && event.error.stack) ? event.error.stack : null
    });
});
window.addEventListener('unhandledrejection', function(event) {
    window.webkit.messageHandlers.jsError.postMessage({
        message: event.reason && event.reason.message ? event.reason.message : 'Unhandled promise rejection',
        error: event.reason && event.reason.stack ? event.reason.stack : null
    });
});"
